# File: bootstrap/state-backend.tf
# Run ONCE to create the shared state store and the lock table.
# This itself uses LOCAL state (chicken-and-egg), then you protect it.
resource "aws_s3_bucket" "tf_state" {
  bucket = "nbi-tf-state"
}

# Versioning lets us recover a previous state file if one gets corrupted.
resource "aws_s3_bucket_versioning" "tf_state" {
  bucket = aws_s3_bucket.tf_state.id
  versioning_configuration { status = "Enabled" }
}

# State contains secrets (DB endpoints), so encrypt it at rest.
resource "aws_s3_bucket_server_side_encryption_configuration" "tf_state" {
  bucket = aws_s3_bucket.tf_state.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "aws:kms" }
  }
}

# The DynamoDB lock table. LockID is the required primary key.
resource "aws_dynamodb_table" "tf_locks" {
  name         = "nbi-tf-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
}
```

```hcl
# File: services/ledger/production/backend.tf
# Each environment gets a UNIQUE state key -> isolation.
terraform {
  backend "s3" {
    bucket         = "nbi-tf-state"
    key            = "ledger/production/terraform.tfstate"  # unique per env
    region         = "ap-south-1"
    dynamodb_table = "nbi-tf-locks"                          # locking
    encrypt        = true
  }
}
```

