```hcl
# File: modules/rds-postgres/main.tf
# Reusable, SECURE-BY-DEFAULT database module. Every team calls this
# instead of hand-writing a DB, so no one can forget encryption.
resource "aws_db_instance" "this" {
  identifier              = var.identifier
  engine                  = "postgres"
  engine_version          = "15.5"
  instance_class          = var.instance_class
  allocated_storage       = var.allocated_storage
  storage_encrypted       = true                 # forced ON — bank rule
  backup_retention_period = var.backup_retention # always backed up
  deletion_protection     = var.deletion_protection
  manage_master_user_password = true
  tags = var.tags
}
```

```hcl
# File: modules/rds-postgres/outputs.tf
output "endpoint" {
  value       = aws_db_instance.this.endpoint
  description = "host:port the service connects to"
}
```

```hcl
# File: services/ledger/production/main.tf
# The team CALLS the shared module, pinning its version with ?ref.
module "ledger_db" {
  source            = "git::https://git.nbi.internal/infra/modules.git//rds-postgres?ref=v2.1.0"
  identifier        = "nbi-ledger-production"
  instance_class    = "db.r6g.large"
  allocated_storage = 100
  backup_retention  = 30
  deletion_protection = true
  tags = { Application = "account-ledger-service", Environment = "production" }
}

output "ledger_db_endpoint" {
  value = module.ledger_db.endpoint
}
```

```yaml
# File: .github/workflows/terraform.yml
# CI drives plan on PR, apply ONLY after merge + manual approval.
name: terraform
on:
  pull_request:
    paths: ["services/**"]
  push:
    branches: [main]
    paths: ["services/**"]

jobs:
  plan:
    if: github.event_name == 'pull_request'
    runs-on: ubuntu-latest
    permissions:
      id-token: write   # OIDC short-lived creds, NOT static keys
      pull-requests: write
    steps:
      - uses: actions/checkout@v4
      - uses: hashicorp/setup-terraform@v3
      - run: terraform -chdir=services/ledger/production init
      - run: terraform -chdir=services/ledger/production plan -no-color | tee plan.txt
      # A step here posts plan.txt as a PR comment for human review.

  apply:
    if: github.event_name == 'push'
    runs-on: ubuntu-latest
    environment: production   # requires manual approval in GitHub
    permissions:
      id-token: write
    steps:
      - uses: actions/checkout@v4
      - uses: hashicorp/setup-terraform@v3
      - run: terraform -chdir=services/ledger/production init
      - run: terraform -chdir=services/ledger/production apply -auto-approve
```

