package com.bank.ledger.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

// The module's output endpoint flows into the app's environment via the
// deploy step. The app never knows or cares which team's module produced it.
@Component
public class LedgerEndpointHolder {

    private final String endpoint;

    public LedgerEndpointHolder(@Value("${LEDGER_DB_ENDPOINT}") String endpoint) {
        this.endpoint = endpoint;
    }

    public String jdbcUrl() {
        return "jdbc:postgresql://" + endpoint + "/ledgerdb";
    }
}
